import{_ as t,c as s,a as l,o as i}from"./app-5valQcRL.js";const a={};function d(n,e){return i(),s("div",null,[...e[0]||(e[0]=[l(`<h1 id="博客写作风格指南" tabindex="-1"><a class="header-anchor" href="#博客写作风格指南"><span>博客写作风格指南</span></a></h1><h2 id="文章结构" tabindex="-1"><a class="header-anchor" href="#文章结构"><span>文章结构</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">---</span>
<span class="line">title: XXX</span>
<span class="line">date: YYYY/MM/DD</span>
<span class="line">categories:</span>
<span class="line">  - 分类名</span>
<span class="line">tags:</span>
<span class="line">  - 标签1</span>
<span class="line">  - 标签2</span>
<span class="line">---</span>
<span class="line"></span>
<span class="line">## 1. 一级标题（动机 / 核心概念）</span>
<span class="line">### 1.1 子标题</span>
<span class="line">### 1.2 子标题</span>
<span class="line">...</span>
<span class="line"></span>
<span class="line">## 2. 一级标题（结构拆解 / 核心内容）</span>
<span class="line">...</span>
<span class="line"></span>
<span class="line">## N. 知识扩展（可选，与主体解耦）</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>二级标题编号为 <code>## 1.</code>、<code>## 2.</code> ...</li><li>三级标题编号为 <code>### 1.1</code>、<code>### 1.2</code> ...</li><li>二级标题数量控制在 3-5 个</li><li>最后一个二级标题通常是「知识扩展」，可跳过不影响主线</li></ul><h2 id="每节内部节奏" tabindex="-1"><a class="header-anchor" href="#每节内部节奏"><span>每节内部节奏</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">直觉/类比 → 数学公式 → 数值例子 → 代码 → &quot;一句话记住&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="格式工具箱" tabindex="-1"><a class="header-anchor" href="#格式工具箱"><span>格式工具箱</span></a></h2><table><thead><tr><th>工具</th><th>用法</th><th>示例</th></tr></thead><tbody><tr><td><code>==text==</code></td><td>高亮强调</td><td><code>==梯度是累加的==</code></td></tr><tr><td><code>&gt;</code></td><td>金句 / 一句话记住</td><td><code>&gt; 一句话记住：...</code></td></tr><tr><td>表格</td><td>对比 / 参数表</td><td>管道符表格</td></tr><tr><td><code>$$</code></td><td>LaTeX公式</td><td><code>$$ \\nabla f $$</code></td></tr><tr><td><code>![alt](path =560x)</code></td><td>配图，指定宽度</td><td><code>![Fig](/img.png =560x)</code></td></tr><tr><td>code-group</td><td>多 tab 代码</td><td>vuepress 自定义容器</td></tr><tr><td><code>---</code></td><td>段落分隔（少用）</td><td></td></tr></tbody></table><h2 id="语言风格" tabindex="-1"><a class="header-anchor" href="#语言风格"><span>语言风格</span></a></h2><ul><li>中文为主，英文术语保留</li><li>对话式，常用「你可能会问...」「想象你在...」</li><li>设「设计哲学」小节讲 WHY</li><li>每个抽象概念配一个生活化类比</li><li>前言/后记简洁，不要铺垫</li></ul><h2 id="配图规范" tabindex="-1"><a class="header-anchor" href="#配图规范"><span>配图规范</span></a></h2><ul><li>生成脚本位于 <code>scripts/image_gen/</code> 下</li><li>运行 <code>python scripts/image_gen/xxx.py</code> 生成配图</li><li>图片保存到 <code>.vuepress/public/DeepLearning/&lt;分类&gt;/</code></li><li>引用格式：<code>![Fig.N 标题](/DeepLearning/&lt;分类&gt;/xxx.png)</code>（不加宽度参数）</li><li>图片尺寸规则：要么不加尺寸（全宽自适应），要么只加 <code>=560x</code>（PC 阅读舒适宽度）</li><li>禁用 <code>=880x</code>、<code>=960x</code> 等自定义大宽度</li><li>统一使用 matplotlib，风格参数： <ul><li>DPI: 120</li><li>Color palette: <code>#4ECDC4</code>, <code>#45B7D1</code>, <code>#FF6B6B</code>, <code>#6B5B95</code>, <code>#FFD93D</code></li><li>Font: <code>Arial Unicode MS</code></li></ul></li></ul><h2 id="解耦原则" tabindex="-1"><a class="header-anchor" href="#解耦原则"><span>解耦原则</span></a></h2><table><thead><tr><th>主题</th><th>归属系列</th><th>不串门</th></tr></thead><tbody><tr><td>网络结构</td><td>NetworkStructure</td><td>不写激活函数导数、不写优化器细节、不写损失函数</td></tr><tr><td>激活函数</td><td>ActivationFunction</td><td>不写网络结构细节</td></tr><tr><td>优化器及其他</td><td>Optimizer</td><td>不写损失函数</td></tr><tr><td>损失函数</td><td>LossFunction</td><td>不写优化器</td></tr><tr><td>训练算法</td><td>EpochalAlgorithms</td><td>跨时代算法</td></tr></tbody></table><ul><li>网络结构篇提激活函数时只写「插入 σ」，不展开</li><li>扩展知识（如通用近似定理、信息论、感受野）放在最后一级标题，与主体解耦</li></ul><h2 id="常见写作错误-避免" tabindex="-1"><a class="header-anchor" href="#常见写作错误-避免"><span>常见写作错误（避免）</span></a></h2><ol><li>在「网络结构」里大篇幅写激活函数 → 激活函数有专属系列</li><li>二级标题过多 → 控制在 3-5 个，同类内容合并</li><li>忘记配图 → 每篇至少 2-3 张图，可视化优先</li><li>只讲 WHAT 不讲 WHY → 必须有「设计哲学」或类比解释</li><li>不用<code>——</code>（em dash）替换冒号或连接词——改用<code>：</code>（冒号）或<code>，</code>（逗号）+ 关联词（因为、所以、但等）</li><li>代码和解释脱节 → 先展示用户视角 API，后展示底层发生了什么</li></ol><h2 id="写后检查清单" tabindex="-1"><a class="header-anchor" href="#写后检查清单"><span>写后检查清单</span></a></h2><p>每次写完文章后逐条确认：</p><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <strong>图引用了正确的编号</strong> — <code>![Fig.N]</code> 的 N 和实际引用的图片一致，文章上下文描述的内容与图画的内容对应</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <strong>无默认知识假设</strong> — 所有关键概念都从直觉讲起，不假设读者已掌握（如「通道/厚度」不能默认读者理解）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <strong>实例 vs 家族区分</strong> — 不要混淆结构家族（如 CNN）和具体实例（如 LeNet）。文章开头就界定清楚</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <strong>扩展内容合一</strong> — 扩展知识统一放在一个二级标题下，用三级标题分隔不同话题，不另开多个二级标题</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <strong>配图间距</strong> — matplotlib 的 <code>plt.tight_layout()</code> + <code>fig.suptitle</code> 组合可能造成标题和内容间距过大，画完后肉眼检查</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <strong>合并后序号连续</strong> — 段落合并/删除后，检查三级标题编号是否连续（不出现 3.1 → 3.3 跳号）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <strong>论文真实结构</strong> — 写具体网络（LeNet、VGG、ResNet）时，用论文中的真实层配置（核大小、通道数、形状变化），不写通用简化版</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <strong>激活函数随论文</strong> — 如果该网络论文用 tanh/sigmoid，就写 tanh/sigmoid，不需要为了统一改成 ReLU</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <strong>vuepress dev 无报错</strong> — 启动本地 serve，确认文章编译无新错误</li></ul>`,20)])])}const o=t(a,[["render",d]]),r=JSON.parse('{"path":"/AIAgent/BLOG_STYLE_GUIDE.html","title":"博客写作风格指南","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"文章结构","slug":"文章结构","link":"#文章结构","children":[]},{"level":2,"title":"每节内部节奏","slug":"每节内部节奏","link":"#每节内部节奏","children":[]},{"level":2,"title":"格式工具箱","slug":"格式工具箱","link":"#格式工具箱","children":[]},{"level":2,"title":"语言风格","slug":"语言风格","link":"#语言风格","children":[]},{"level":2,"title":"配图规范","slug":"配图规范","link":"#配图规范","children":[]},{"level":2,"title":"解耦原则","slug":"解耦原则","link":"#解耦原则","children":[]},{"level":2,"title":"常见写作错误（避免）","slug":"常见写作错误-避免","link":"#常见写作错误-避免","children":[]},{"level":2,"title":"写后检查清单","slug":"写后检查清单","link":"#写后检查清单","children":[]}],"git":{"createdTime":null,"updatedTime":null,"contributors":[]},"filePathRelative":"AIAgent/BLOG_STYLE_GUIDE.md"}');export{o as comp,r as data};
